BEGIN READ ONLY;
SET LOCAL statement_timeout='5s'; SET LOCAL lock_timeout='1s'; SET LOCAL search_path=pg_catalog;
SELECT jsonb_build_object('tipo','preflight-emissores-chat-minimo-v1','conferidaEm',clock_timestamp(),'banco',current_database(),'phoneId','648633368337527',
 'configuracoes',(SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'fingerprint',encode(sha256(convert_to(whatsapp_access_token,'UTF8')),'hex')) ORDER BY id),'[]') FROM public.nina_settings WHERE whatsapp_phone_number_id='648633368337527' AND nullif(whatsapp_access_token,'') IS NOT NULL),
 'configuracoesSha256',encode(sha256(convert_to(coalesce((SELECT jsonb_agg(to_jsonb(n) ORDER BY n.id)::text FROM public.nina_settings n WHERE n.whatsapp_phone_number_id='648633368337527'),'[]'),'UTF8')),'hex'),'claimSha256',encode(sha256(convert_to(pg_get_functiondef('public.claim_send_queue_batch(integer)'::regprocedure),'UTF8')),'hex'),
 'claimCriterioCompativel',regexp_replace(pg_get_functiondef('public.claim_send_queue_batch(integer)'::regprocedure),'\s+',' ','g') LIKE '%WHERE status = ''pending''%' AND regexp_replace(pg_get_functiondef('public.claim_send_queue_batch(integer)'::regprocedure),'\s+',' ','g') LIKE '%SET status = ''processing''%' AND pg_get_functiondef('public.claim_send_queue_batch(integer)'::regprocedure) LIKE '%RETURNING s.*%',
 'visibilidadeIntegral',NOT EXISTS(SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace JOIN pg_roles r ON r.rolname=current_user WHERE n.nspname='public' AND c.relname IN ('nina_settings','send_queue') AND c.relrowsecurity AND NOT(r.rolsuper OR r.rolbypassrls OR(c.relowner=r.oid AND NOT c.relforcerowsecurity))),'podeAtualizarConfiguracoes',has_table_privilege(current_user,'public.nina_settings','SELECT') AND has_table_privilege(current_user,'public.nina_settings','UPDATE') AND has_table_privilege(current_user,'public.nina_settings','TRIGGER') AND EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.rolname=current_user WHERE c.oid='public.nina_settings'::regclass AND(r.rolsuper OR pg_has_role(current_user,c.relowner,'USAGE'))),
 'podeGuardarFila',has_table_privilege(current_user,'public.send_queue','SELECT') AND has_table_privilege(current_user,'public.send_queue','UPDATE') AND has_table_privilege(current_user,'public.send_queue','TRIGGER') AND EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.rolname=current_user WHERE c.oid='public.send_queue'::regclass AND(r.rolsuper OR pg_has_role(current_user,c.relowner,'USAGE'))),'podeCriarSchema',has_database_privilege(current_user,current_database(),'CREATE'),
 'outrosNumerosConfigurados',(SELECT count(*) FROM public.nina_settings WHERE nullif(whatsapp_access_token,'') IS NOT NULL AND whatsapp_phone_number_id IS DISTINCT FROM '648633368337527')) AS preflight;
ROLLBACK;
